class Solution {
public:
    long long numberOfWeeks(vector<int>& milestones) {
        long long total = 0;
        int maxM = 0;
        for (int m : milestones) {
            total += m;
            if (m > maxM) maxM = m;
        }
        long long rest = total - maxM;
        if (maxM <= rest + 1) return total;
        return 2 * rest + 1;
    }
};
